pub(crate) fn rtt_fill1(b: &crate::port::Bitmap, x0: i32, y0: i32, x1: i32, y1: i32, v: i32) -> i32 {
    let mut y: i32 = y0;
    let mut x: i32 = 0;
    while y < y1 {
        x = x0;
        while x < x1 {
            crate::port::bitmap_set_u8(b, x, y, 0, v);
            x += 1;
        }
        y += 1;
    }
    return 0;
}
